import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public final class KruskalMST {
    private KruskalMST() {
    }

    public static int kruskalsMST(int vertexCount, int[][] edgeRows) {
        return minimumSpanningTree(vertexCount, edgeRows).totalWeight();
    }

    public static int minimumSpanningTreeCost(int vertexCount, List<Edge> edges) {
        return minimumSpanningTree(vertexCount, edges).totalWeight();
    }

    public static MstResult minimumSpanningTree(int vertexCount, int[][] edgeRows) {
        return minimumSpanningTree(vertexCount, toEdges(edgeRows));
    }

    public static MstResult minimumSpanningTree(int vertexCount, List<Edge> edges) {
        validateVertexCount(vertexCount);
        List<Edge> sortedEdges = normalizeEdges(vertexCount, edges);
        return buildMinimumSpanningTree(vertexCount, sortedEdges);
    }

    private static MstResult buildMinimumSpanningTree(int vertexCount, List<Edge> sortedEdges) {
        int targetEdgeCount = requiredEdgeCount(vertexCount);
        DisjointSet disjointSet = new DisjointSet(vertexCount);
        List<Edge> selectedEdges = new ArrayList<>(targetEdgeCount);
        int totalWeight = 0;

        for (Edge edge : sortedEdges) {
            if (disjointSet.unionIfSeparate(edge.from(), edge.to())) {
                selectedEdges.add(edge);
                totalWeight += edge.weight();

                if (selectedEdges.size() == targetEdgeCount) {
                    break;
                }
            }
        }

        return new MstResult(totalWeight, selectedEdges, selectedEdges.size() == targetEdgeCount);
    }

    private static List<Edge> normalizeEdges(int vertexCount, List<Edge> edges) {
        if (edges == null) {
            throw new IllegalArgumentException("Edge list cannot be null.");
        }

        List<Edge> sortedEdges = new ArrayList<>(edges.size());

        for (Edge edge : edges) {
            if (edge == null) {
                throw new IllegalArgumentException("Edge list cannot contain null values.");
            }

            validateEdge(edge, vertexCount);
            sortedEdges.add(edge);
        }

        sortedEdges.sort(Comparator.comparingInt(Edge::weight));
        return sortedEdges;
    }

    private static List<Edge> toEdges(int[][] edgeRows) {
        if (edgeRows == null) {
            throw new IllegalArgumentException("Edge rows cannot be null.");
        }

        List<Edge> edges = new ArrayList<>(edgeRows.length);

        for (int[] edgeRow : edgeRows) {
            if (edgeRow == null || edgeRow.length != 3) {
                throw new IllegalArgumentException("Each edge must contain exactly 3 values: from, to, weight.");
            }

            edges.add(new Edge(edgeRow[0], edgeRow[1], edgeRow[2]));
        }

        return edges;
    }

    private static void validateVertexCount(int vertexCount) {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("Vertex count cannot be negative.");
        }
    }

    private static int requiredEdgeCount(int vertexCount) {
        return vertexCount == 0 ? 0 : vertexCount - 1;
    }

    private static void validateEdge(Edge edge, int vertexCount) {
        if (edge.from() < 0 || edge.from() >= vertexCount || edge.to() < 0 || edge.to() >= vertexCount) {
            throw new IllegalArgumentException("Edge contains a vertex index outside the valid range.");
        }
    }

    public record Edge(int from, int to, int weight) {
    }

    public record MstResult(int totalWeight, List<Edge> edges, boolean spansAllVertices) {
        public MstResult {
            edges = List.copyOf(edges);
        }
    }

    private static final class DisjointSet {
        private final int[] parent;
        private final int[] rank;

        private DisjointSet(int size) {
            parent = new int[size];
            rank = new int[size];

            for (int vertex = 0; vertex < size; vertex++) {
                parent[vertex] = vertex;
                rank[vertex] = 1;
            }
        }

        private int find(int vertex) {
            if (parent[vertex] != vertex) {
                parent[vertex] = find(parent[vertex]);
            }

            return parent[vertex];
        }

        private boolean unionIfSeparate(int first, int second) {
            int firstRoot = find(first);
            int secondRoot = find(second);

            if (firstRoot == secondRoot) {
                return false;
            }

            if (rank[firstRoot] < rank[secondRoot]) {
                parent[firstRoot] = secondRoot;
            } else if (rank[firstRoot] > rank[secondRoot]) {
                parent[secondRoot] = firstRoot;
            } else {
                parent[secondRoot] = firstRoot;
                rank[firstRoot]++;
            }

            return true;
        }
    }
}

