    public static void main(String[] args) {
        int[][] edges = {
            {0, 1, 10},
            {1, 3, 15},
            {2, 3, 4},
            {2, 0, 6},
            {0, 3, 5}
        };

        KruskalMST.MstResult result = KruskalMST.minimumSpanningTree(4, edges);
        System.out.println(result.totalWeight());
    }
}

